        delete_4:
          "dEvaradidella dEvarige ella endu oraluta।\nAvudanum avana nirNayake biDadeye tAM ॥\ndAvanta baDuta tanna icCheyane ghOShisuva ।\nbhAvaventaha bhakuti? - Mankutimma ॥ 581 ॥",
        delete: "ದಾವಂತಬಡುತ=ಪರದಾಡುತ್ತಾ",
        kannada_explanation:
          "ಈ ಜಗತ್ತೆಲ್ಲವೂ ಆ ದೇವರದು ಮತ್ತು ಇಲ್ಲಿರುವುದೆಲ್ಲವೂ ಆ ದೇವರಿಗಾಗಿಯೇ ಇದೆ ಎಂದು ವಟಗುಟ್ಟುತ್ತಾ ಯಾವುದನ್ನೂ ಅವನ ನಿರ್ಣಯಕ್ಕೆ ಬಿಡದೆ, ತಾನೇ ಎಲ್ಲದಕ್ಕೂ ದಾವಂತಪಡುತ್ತಾ, ತನ್ನದೇ ಆದ ನಿರ್ಣಯಗಳನ್ನು ಸದಾಕಾಲ ಘೋಷಿಸುತ್ತಾ ಇರುವುದು ಯಾವ ರೀತಿಯ ಭಕ್ತಿ ಎಂದು ಪ್ರಶ್ನಿಸುತ್ತಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.",
        delete_2:
          'ಎಲ್ಲವೂ ಆ ದೇವರಿಂದ ಆದದ್ದು. ಆ ದೇವರೇ ಎಲ್ಲವೂ ಆಗಿ ಪ್ರಕಟಗೊಂಡಿದ್ದಾನೆ. ಈ ಜಗತ್ತಿನಲ್ಲಿರುವುದೆಲ್ಲವೂ ಅವನೇ ಆಗಾಗಿ, ಅವನಿಗಾಗಿಯೇ ಆಗಿದೆ. ಇಂತಹ ಭಾವವನ್ನು ಈಶಾವಾಸ್ಯೋಪನಿಷತ್ತು"ಈಶಾವಾಸ್ಯಮಿದಂ ಸರ್ವಂ ಯತ್ ಕಿಚಂತ್ ಜಗತ್ಯಾಮ್ ಜಗತ್, ತೇನ ತ್ಯಕ್ತೇನ ಭುಂಜೀತಾ ಮಾ ಗೃದಃ ಕಸ್ಯಸ್ವಿದ್ಧನಂ"ಎನ್ನುತ್ತದೆ. ನಾವೂ ಸಹ, ಈ ಜಗತ್ತಿನ ಎಲ್ಲವೂ ಅವನಿಗೆ ಸೇರಿದ್ದು, ನಾವು ಉಡುವ ಮತ್ತು ಉಣ್ಣುವುದೆಲ್ಲವೋ ಆ ಪರಮಾತ್ಮನ ಪ್ರಸಾದವೆಂಬಂತೆ ಇರಬೇಕು, ಎಂದು ಬಾಯಲ್ಲಿ ಹೇಳುತ್ತೇವೆ, ಸುಮ್ಮನೆ ವಟಗುಟ್ಟುತ್ತೇವೆ. ಸತ್ಯವಾಗಿ ಆತ್ಮಾವಲೋಕನ ಮಾಡಿಕೊಂಡರೆ ನಮ್ಮ ಆಲೋಚನೆಯ ಟೊಳ್ಳುತನದ ಅರಿವಾಗುತ್ತದೆ. ಏಕೆಂದರೆ ನಾವು ಸದಾಕಾಲ ಮಾಡುವ ಎಲ್ಲ ಕೆಲಸಗಳನ್ನೂ "ನಾನು ಮಾಡುತ್ತೇನೆ, ನಾನು ಸಾಧಿಸಿದೆ, ನಾನು ಪಡೆದುಕೊಂಡೆ, ನಾ ಗಳಿಸಿದೆ. ನಾ ಜಯಿಸಿದೆ" ಇತ್ಯಾದಿಯಾಗಿ ಹೇಳಿಕೊಳ್ಳುತ್ತೇವೆ. ಒಂದು ಕಡೆ ಎಲ್ಲವೂ ಪರಮಾತ್ಮನೇ, ಪರಮಾತ್ಮನಿಂದ ಮತ್ತು ಪರಮಾತ್ಮನಿಗೆ ಎಂದು ಎನ್ನುವ ನಾವು ಹಾಗೆ ಹೇಳಿಕೊಳ್ಳುವುದು ‘ಅಭಾಸ’ ವಲ್ಲವೇ? ಇದು ಪರಮಾತ್ಮನಲ್ಲಿ ಸರಿಯಾದ ಭಕ್ತಿಯೇ? ಎಂದು ಪ್ರಶ್ನಿಸುತ್ತಾರೆ ಮಾನ್ಯ ಗುಂಡಪ್ಪನವರು ಈ ಮುಕ್ತಕದಲ್ಲಿ.ಭಕ್ತಿಗೆ ಸಮರ್ಪಣಾ ಭಾವ ಬೇಕು. ಸಮರ್ಪಣೆ ಎಂದರೆ ಸಕಲವನ್ನೂ ಆ ಪರಮಾತ್ಮನ ಚರಣಗಳಿಗೆ ಅರ್ಪಿಸಿಬಿಡುವುದು. ಇದಕ್ಕೆ ಪ್ರಪತ್ತಿಯೆನ್ನುತ್ತಾರೆ ಸಂಪೂರ್ಣ ಶರಣಾಗತಿಯ ಅರ್ಥದಲ್ಲಿ. ಆದರೆ ಹಾಗೆ ಸಂಪೂರ್ಣ ಶರಣಾಗತಿಯ ಹಂತಕ್ಕೆ ಹೋಗಬೇಕಾದರೆ ಬಹಳ ದೊಡ್ಡ ಸಾಧನೆ ಬೇಕು. ಆ ಭಗವಂತನಿಂದ ಸೃಷ್ಟಿಸಲ್ಪಟ್ಟ ಈ ಜಗತ್ತಿನಲ್ಲಿ ನಾವೂ ಒಂದು ಭಾಗವಷ್ಟೇ. ನಮಗೆ ಒಂದು ಪ್ರಮಾಣದ ಶಕ್ತಿಯಿದೆ. ಆ ಶಕ್ತಿಗೆ ಮೂಲ ಮತ್ತು ಪ್ರೇರಕವಾದ ಶಕ್ತಿಯೇ ಆ ಪರಮಾತ್ಮ. ನಾವು ಮಾಡುವ ಕೆಲಸವನ್ನು, ಆ ಪರಮಾತ್ಮನಿಂದ ನಿಯಮಿಸಲ್ಪಟ್ಟ ಕರ್ತವ್ಯವೆಂದು ಭಾವಿಸಿ, ಪೂರ್ವ ಅಥವಾ ಉತ್ತರದ ಫಲಾಪೇಕ್ಷೆಯಿಲ್ಲದೆ, ಅಹಂಕಾರ ರಹಿತರಾಗಿ ಆ ಕೆಲಸವನ್ನು ಮಾಡಿ, ಸಂದ ಫಲವನ್ನು ಪರಮಾತ್ಮನ ಪ್ರಸಾದವೆಂದು ಸ್ವೀಕರಿಸಿ, ತೃಪ್ತಿಹೊಂದಿದರೆ ಅದು ನಿಜವಾದ ಭಕ್ತಿಭಾವವಾಗುತ್ತದೆ. ಇಂತಹ ಅನನ್ಯವಾದ ಭಕ್ತಿಯ ಭಾವವನ್ನು ಭಾರತದ ಎಲ್ಲಾ ಮಹನೀಯ ಸಂತರುಗಳೂ ಸಹ ಪ್ರತಿಪಾದಿಸಿದ್ದಾರೆನಮ್ಮ ನಿರ್ಣಯಗಳು ಮತ್ತು ನಮ್ಮ ಭಾವನೆಗಳಿಗೂ, ನಾವು ಮಾಡುವ ಕೆಲಸಗಳು ಮತ್ತು ಅದರಿಂದ ನಮಗೆ ಸಿಗುವ ಫಲಗಳು, ಹೀಗೆ ಎಲ್ಲಕ್ಕೂ ಆ ದೇವರೇ ಕಾರಣನೆಂದು, ನಾವು ನಿಮಿತ್ತ ಮಾತ್ರರೆಂದು ದೃಢವಾದ ನಂಬಿಕೆ ನಮ್ಮಲ್ಲಿ ಎಂದು ಬರುತ್ತದೋ ಅಂದು ನಾವು ನಿಜ ಭಕ್ತಿಯೆಡೆಗೆ ಹೆಜ್ಜೆ ಹಾಕುತ್ತಿದ್ದೇವೆ ಎಂದು ಅರ್ಥ. ಎಷ್ಟು ಪೂಜೆ ಪುನಸ್ಕಾರಗಳನ್ನು ಮಾಡಿದರೂ ಅಂತಹ ದೃಢಭಾವ ನಮ್ಮಲ್ಲಿ ನೆಲೆಯಾಗದಿದ್ದರೆ ಭಕ್ತಿ ಪೂರ್ಣವಾಗುವುದಿಲ್ಲ. ಅಂತಹ ಅಪರಿಪೂರ್ಣ ಭಕ್ತಿಯಿಂದ ಪರಿಪೂರ್ಣ ಭಕ್ತಿಯೆಡೆಗೆ ನಮ್ಮ ಪ್ರಯಾಣ ಸಾಗಬೇಕು.',
